const rows = $input.all().map(i => i.json);

// Group by schema → table → columns
const schemas = {};
for (const row of rows) {
  const key = `${row.schema_name}.${row.table_name}`;
  if (!schemas[key]) schemas[key] = [];

  let col = `  - ${row.column_name} (${row.data_type}`;
  if (row.is_pk === 'PK') col += ', PRIMARY KEY';
  if (row.is_fk === 'FK') col += ', FK';
  if (row.is_nullable === false || row.is_nullable === 0) col += ', NOT NULL';
  if (row.check_constraint) col += `, CHECK: ${row.check_constraint}`;
  col += ')';

  schemas[key].push(col);
}

// Build readable markdown
let schemaText = '# UHIP Database Schema\n\n';
for (const [table, cols] of Object.entries(schemas)) {
  schemaText += `## ${table}\n${cols.join('\n')}\n\n`;
}

return [{ json: { schemaText } }];

const messages = $input.all();
const result = messages.map((msg) => {
  const text = msg.json.result.text;
  const telegram_id = msg.json.result.chat.id;
  const patient_name = text.split("Patient Name:")[1]?.split("\n")[0]?.trim();
  const hospital_name = text.split("Hospital:")[1]?.split("\n")[0]?.trim();
  const department_name = text.split("Department:")[1]?.split("\n")[0]?.trim();
  const doctor_name = text.split("Doctor:")[1]?.split("\n")[0]?.trim();
  const visit_date_raw = text.split("Date:")[1]?.split("\n")[0]?.trim();
  const visit_time = text.split("Time:")[1]?.split("\n")[0]?.trim();
  const visit_date = new Date(
    visit_date_raw.replace(/(\d+)(st|nd|rd|th)/, "$1"),
  )
    .toISOString()
    .split("T")[0];
  return {
    patient_name,
    telegram_id,
    hospital_name,
    department_name,
    doctor_name,
    visit_date,
    visit_time,
  };
});

return result;
